import { useCallback, useMemo, useState } from 'react';

import {
  buildVisibleRows,
  DrillDownRow,
  mapWatchtowerApiColumnGroups,
  mapWatchtowerApiRows,
  WATCHTOWER_TABLE_API_MOCK,
  WATCHTOWER_TABLE_COMPARE_MOCK,
} from 'components/DrillDownTable';
import type { DrillDownColumnGroup } from 'components/DrillDownTable';

export interface UseWatchTowerDrillDownTableResult {
  rows: DrillDownRow[];
  columnGroups: DrillDownColumnGroup[];
  expandedIds: Set<string>;
  onToggleRow: (id: string) => void;
  compareChecked: boolean;
  onCompareChange: (checked: boolean) => void;
  compareTooltip: string | undefined;
}

export function useWatchTowerDrillDownTable(): UseWatchTowerDrillDownTableResult {
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const [compareChecked, setCompareChecked] = useState(false);

  const apiData = useMemo(
    () =>
      compareChecked
        ? WATCHTOWER_TABLE_COMPARE_MOCK
        : WATCHTOWER_TABLE_API_MOCK,
    [compareChecked],
  );

  const onToggleRow = useCallback((id: string) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }, []);

  const columnGroups = useMemo(
    () => mapWatchtowerApiColumnGroups(apiData.column_groups),
    [apiData.column_groups],
  );

  const allRows = useMemo(
    () => mapWatchtowerApiRows(apiData.rows),
    [apiData.rows],
  );

  const rows = useMemo(
    () => buildVisibleRows(allRows, expandedIds),
    [allRows, expandedIds],
  );

  return {
    rows,
    columnGroups,
    expandedIds,
    onToggleRow,
    compareChecked,
    onCompareChange: setCompareChecked,
    compareTooltip: apiData.compare_tooltip,
  };
}
